{
  "states": [
    "Initial State",
    "Mail Transaction In Progress"
  ],
  "transitions": [
    {
      "from": "Initial State",
      "event": "EHLO or HELO",
      "action": "clear all buffers and reset state tables",
      "to": "Initial State"
    },
    {
      "from": "Initial State",
      "event": "MAIL",
      "action": "reset reverse-path buffer, forward-path buffer, mail data buffer; insert reverse-path information",
      "to": "Mail Transaction In Progress"
    },
    {
      "from": "Mail Transaction In Progress",
      "event": "RCPT",
      "action": "append forward-path argument to forward-path buffer",
      "to": "Mail Transaction In Progress"
    },
    {
      "from": "Mail Transaction In Progress",
      "event": "DATA",
      "action": "process stored recipients and mail data; clear buffers",
      "to": "Initial State"
    },
    {
      "from": "Mail Transaction In Progress",
      "event": "RSET",
      "action": "discard stored sender, recipients, and mail data; clear all buffers and state tables",
      "to": "Initial State"
    },
    {
      "from": "Mail Transaction In Progress",
      "event": "EHLO (re-issued)",
      "action": "clear all buffers and reset the state exactly as if a RSET command had been issued",
      "to": "Initial State"
    }
  ]
}

