      "event": "MAIL command",
      "action": "reset all state tables and buffers",
      "to": "Mail Transaction Open"
    },
    {
      "from": "Mail Transaction Open",
      "event": "RCPT command",
      "action": "store forward-path",
      "to": "Mail Transaction Open"
    },
    {
      "from": "Mail Transaction Open",
      "event": "DATA command",
      "action": "consider succeeding lines as message text until end of mail data indicator",
      "to": "Mail Transaction Complete"
    },
    {
      "from": "Mail Transaction Complete",
      "event": "end of mail data indicator",
      "action": "confirm transaction and process stored recipients and mail data",
      "to": "Mail Transaction Open"
    }
  ]
}

